{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio in the district (number of students per teacher). Constructed as total students divided by number of teachers (FTE). Hypothesized independent variable: lower ratio (fewer students per teacher) is associated with higher academic performance.",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "Average academic performance for the district, computed as the mean of the reading and math Stanford-9 scores (5th grade). Higher values indicate better performance.",
      "columns": [
        "AvgTestScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district-level). Controls for resource level per pupil.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Expenditure"
        ]
      },
      {
        "description": "Average district income (in USD 1,000). Controls for socioeconomic status of district.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Income"
        ]
      },
      {
        "description": "Percent of students qualifying for CalWorks (income assistance). Controls for poverty levels.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PctCalWorks"
        ]
      },
      {
        "description": "Percent of students qualifying for reduced-price lunch. Controls for socioeconomic disadvantage.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PctLunch"
        ]
      },
      {
        "description": "Percent of English learners (students for whom English is a second language). Controls for language support needs that can affect test scores.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PctEnglishLearners"
        ]
      },
      {
        "description": "Number of computers per teacher (proxy for in-classroom technology resourcing). Computed as total computers divided by number of teachers (FTE).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputersPerTeacher"
        ]
      },
      {
        "description": "Indicator for grade span (1 if district is KK-08, 0 if KK-06). Controls for structural differences across district types.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Grades_KK08"
        ]
      },
      {
        "description": "County identifier included as a categorical control to soak up regional fixed effects (if desired in extensions).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "County"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    df = df.copy()\n\n    # Ensure required columns exist\n    required = ['students', 'teachers', 'read', 'math', 'computer', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'grades', 'county']\n    missing = [c for c in required if c not in df.columns]\n    if missing:\n        raise ValueError(f\"Missing required columns for transform: {missing}\")\n\n    # Drop rows with missing key numeric inputs\n    df = df.dropna(subset=['students', 'teachers', 'read', 'math'])\n\n    # Remove impossible or zero teacher counts to avoid division by zero\n    df = df[df['teachers'] > 0]\n\n    # Compute student-teacher ratio\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Dependent variable: average of reading and math scores\n    df['AvgTestScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Computers per teacher (proxy for technology resources in classrooms)\n    # If computer is missing or teachers is zero we've already filtered; still guard\n    df['ComputersPerTeacher'] = df['computer'] / df['teachers']\n\n    # Create control columns with clear names used in modeling\n    # Copy existing numeric controls into final column names\n    df['Expenditure'] = df['expenditure']\n    df['Income'] = df['income']\n    df['PctCalWorks'] = df['calworks']\n    df['PctLunch'] = df['lunch']\n    df['PctEnglishLearners'] = df['english']\n\n    # Grades dummy: 1 if KK-08, 0 otherwise (KK-06 or other)\n    # Ensure consistent string representation\n    df['Grades_KK08'] = (df['grades'].astype(str) == 'KK-08').astype(int)\n\n    # Keep county as a categorical variable for optional fixed-effects\n    df['County'] = df['county'].astype('category')\n\n    # Drop rows with missing values in controls that we will include in the model\n    control_cols = ['Expenditure', 'Income', 'PctCalWorks', 'PctLunch', 'PctEnglishLearners', 'ComputersPerTeacher']\n    df = df.dropna(subset=control_cols)\n\n    # Optional: trim extreme outliers in StudentTeacherRatio (e.g., extremely large due to data issues)\n    # We'll keep rows within 1st and 99th percentile to avoid undue influence\n    lower = df['StudentTeacherRatio'].quantile(0.01)\n    upper = df['StudentTeacherRatio'].quantile(0.99)\n    df = df[(df['StudentTeacherRatio'] >= lower) & (df['StudentTeacherRatio'] <= upper)]\n\n    # Final check: ensure no remaining missing in modeling columns\n    model_cols = ['AvgTestScore', 'StudentTeacherRatio'] + control_cols + ['Grades_KK08', 'County']\n    df = df.dropna(subset=model_cols)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fits an OLS model estimating the association between student-teacher ratio and average test score,\n    controlling for expenditure, income, poverty indicators, english learners, technology, and grade-span.\n\n    The model uses robust (HC1) standard errors to guard against heteroskedasticity.\n    Returns the fitted statsmodels results object.\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Ensure dataframe is the transformed one\n    required_cols = ['AvgTestScore', 'StudentTeacherRatio', 'Expenditure', 'Income', 'PctCalWorks', 'PctLunch', 'PctEnglishLearners', 'ComputersPerTeacher', 'Grades_KK08']\n    missing = [c for c in required_cols if c not in df.columns]\n    if missing:\n        raise ValueError(f\"Dataframe missing required columns for modeling: {missing}\")\n\n    # Primary linear specification\n    formula = (\n        'AvgTestScore ~ StudentTeacherRatio + Expenditure + Income + PctCalWorks '\n        '+ PctLunch + PctEnglishLearners + ComputersPerTeacher + Grades_KK08'\n    )\n\n    results = smf.ols(formula, data=df).fit(cov_type='HC1')\n\n    return results\n"
}
